{
  "name": "pairwise_pref_loss",
  "intuition": "This loss computes a pairwise preference score based on the advantage signals, encouraging the model to rank higher advantage pairs more favorably. Using advantage signals directly aligns the loss with the benefit of selecting better options, promoting preference consistency. Incorporating log probabilities stabilizes training, and the pairwise mode enables direct comparison between pairs, suitable for preference optimization.",
  "pseudocode": "loss = mean over pairs of [logsigmoid(advantages)] where advantages = advantage_w - advantage_l",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "logistic",
    "agg_family": "pairwise",
    "constraint_family": "ranking"
  },
  "operators_used": ["logsigmoid", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_diff = ops.sub(adv_w, adv_l)\n    preference_score = ops.logsigmoid(advantage_diff)\n    weighted_score = ops.mul(preference_score, weight)\n    loss = ops.mean(weighted_score)\n    return loss"
}

{
  "name": "loss_rankgap_tanh_advantage",
  "intuition": "shift from margin-based pairwise logsigmoid to rank-based smooth margin loss using tanh on the advantage gap to emphasize medium confidence pairs and enforce a ranking constraint",
  "pseudocode": "diff = log_prob_w - log_prob_l\nscaled_adv = tanh(beta * advantage_gap.detach())\nloss = mean(weight * relu(rank_gap - diff * scaled_adv))",
