  },
  "code": "def generated_loss(batch, model_output, extra):\n    scale = float(extra.get('scale', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch['cost_gap']\n    # Compute scaled cost difference\n    scaled_diff = ops.mul(scale, cost_gap)\n    # Preference score using logsigmoid\n    pref_score = ops.logsigmoid(scaled_diff)\n    # Weighted mean to produce scalar loss\n    loss = ops.mul(pref_score, weight)\n    scalar_loss = ops.mean(loss)\n    return scalar_loss"
}

