{
  "name": "pairwise_advantage_tanh_loss",
  "intuition": "This loss computes the pairwise difference of log probabilities, scales it via tanh for boundedness, and weights it by the advantage gap to emphasize preferred pairs. Using tanh helps capture nonlinear preference severity and stabilizes training. It encourages the model to differentiate pairs based on advantage signals more effectively, aligning with the goal of ranking.",
  "pseudocode": "log_diff = log_prob_w - log_prob_l\nscaled_diff = tanh(beta * log_diff)\nweighted_diff = advantage_gap * scaled_diff\nloss = max(0, margin - weighted_diff)\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "margin"
  },
  "operators_used": ["logsigmoid", "tanh", "mul", "sub", "max", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', None)\n    beta = float(extra.get('beta', 1.0))\n    margin = float(extra.get('margin', 0.0))\n    log_diff = ops.sub(lpw, lpl)\n    scaled_diff = ops.tanh(ops.mul(beta, log_diff))\n    weighted_diff = ops.mul(adv_gap, scaled_diff)\n    raw_loss = ops.sub(margin, weighted_diff)\n    loss = ops.max(raw_loss, ops.zeros_like(raw_loss))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

