  "intuition": "This loss applies a softplus transformation to the difference in log probabilities, smoothing the gradient signal and reducing abrupt changes. By weighting the transformed difference with the squared advantage gap, it emphasizes pairs with stronger preference signals while maintaining stability. This approach softens the penalization, promoting more robust learning of preference hierarchies in RL4CO.",
  "pseudocode": "adv_sq = advantage_gap ^ 2\nscore_diff = log_prob_w - log_prob_l\nloss = softplus(-score_diff) * adv_sq * weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_probability",
    "signal_family": "advantage_gap",
    "link_family": "softplus",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "mul", "softplus", "mean", "pow"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    adv_sq = ops.mul(adv_gap, adv_gap)\n    score_diff = ops.sub(lpw, lpl)\n    loss_raw = ops.mul(ops.softplus(ops.neg(score_diff)), adv_sq)\n    weighted_loss = ops.mul(loss_raw, weight)\n    return ops.mean(weighted_loss)"
}

